import java.nio.file.*;
import java.util.*;
public class Main {
 static byte[] data; static int[] offsets=new int[1024], lengths=new int[1024], wordSlots=new int[2048]; static int wordCount=0;
 static int wordHash(int start,int end){int h=0x811c9dc5;for(int i=start;i<end;i++)h=(h^(data[i]&255))*0x01000193;h^=h>>>16;return h;}
 static void growWords(){int[] old=wordSlots;wordSlots=new int[old.length*2];for(int id:old)if(id!=0){int p=wordHash(offsets[id],offsets[id]+lengths[id])&(wordSlots.length-1);while(wordSlots[p]!=0)p=(p+1)&(wordSlots.length-1);wordSlots[p]=id;}}
 static int intern(int start,int end){if((wordCount+1)*10>=wordSlots.length*7)growWords();int p=wordHash(start,end)&(wordSlots.length-1);while(wordSlots[p]!=0){int id=wordSlots[p];if(lengths[id]==end-start){int j=0;while(j<end-start&&data[offsets[id]+j]==data[start+j])j++;if(j==end-start)return id;}p=(p+1)&(wordSlots.length-1);}int id=++wordCount;if(id==offsets.length){offsets=Arrays.copyOf(offsets,id*2);lengths=Arrays.copyOf(lengths,id*2);}offsets[id]=start;lengths[id]=end-start;wordSlots[p]=id;return id;}
 static class Table {long[] keys=new long[1024],counts=new long[1024];int used;static long hash(long x){x^=x>>>30;x*=0xbf58476d1ce4e5b9L;x^=x>>>27;x*=0x94d049bb133111ebL;return x^(x>>>31);}void grow(){long[] old=keys,oc=counts;keys=new long[old.length*2];counts=new long[keys.length];for(int i=0;i<old.length;i++)if(old[i]!=0){int p=(int)hash(old[i])&(keys.length-1);while(keys[p]!=0)p=(p+1)&(keys.length-1);keys[p]=old[i];counts[p]=oc[i];}}void add(long k){if((long)(used+1)*10>=keys.length*7L)grow();int p=(int)hash(k)&(keys.length-1);while(keys[p]!=0&&keys[p]!=k)p=(p+1)&(keys.length-1);if(keys[p]==0){keys[p]=k;used++;}counts[p]++;}}
 static int cmpWord(int a,int b){int n=Math.min(lengths[a],lengths[b]),x=offsets[a],y=offsets[b];for(int i=0;i<n;i++)if(data[x+i]!=data[y+i])return data[x+i]-data[y+i];return Integer.compare(lengths[a],lengths[b]);}
 static class Row {long k,c;Row(long k,long c){this.k=k;this.c=c;}}
 static int compare(Row a,Row b){int c=Long.compare(b.c,a.c);if(c!=0)return c;c=cmpWord((int)(a.k>>>32),(int)(b.k>>>32));return c!=0?c:cmpWord((int)a.k,(int)b.k);}
 public static void main(String[] args)throws Exception{data=Files.readAllBytes(Path.of(args[0]));for(int i=0;i<data.length;i++)if(data[i]>='A'&&data[i]<='Z')data[i]+=32;Table t=new Table();long total=0,pairs=0;int prev=0;for(int i=0;i<data.length;){byte c=data[i];if(c>='a'&&c<='z'){int start=i++;while(i<data.length&&data[i]>='a'&&data[i]<='z')i++;int id=intern(start,i);total++;if(prev!=0){t.add(((long)prev<<32)|(id&0xffffffffL));pairs++;}prev=id;}else{if(c=='.'||c=='!'||c=='?')prev=0;i++;}}
 ArrayList<Row> top=new ArrayList<>();for(int i=0;i<t.keys.length;i++)if(t.keys[i]!=0&&(top.size()<20||t.counts[i]>=top.get(top.size()-1).c)){Row r=new Row(t.keys[i],t.counts[i]);int p=Collections.binarySearch(top,r,Main::compare);if(p<0)p=-p-1;if(p<20){top.add(p,r);if(top.size()>20)top.remove(20);}}StringBuilder out=new StringBuilder();out.append("words ").append(total).append("\npairs ").append(pairs).append("\ndistinct ").append(t.used).append('\n');for(Row r:top){int a=(int)(r.k>>>32),b=(int)r.k;out.append(r.c).append(' ').append(new String(data,offsets[a],lengths[a],java.nio.charset.StandardCharsets.US_ASCII)).append(' ').append(new String(data,offsets[b],lengths[b],java.nio.charset.StandardCharsets.US_ASCII)).append('\n');}System.out.print(out);}
}
